type Plan = 'starter' | 'growth' | 'enterprise';

interface RawAccount {
  account_id?: unknown;
  company_name?: unknown;
  owner_email?: unknown;
  signed_up_at?: unknown;
  plan?: unknown;
}

interface Account {
  id: number;
  companyName: string;
  ownerEmail: string;
  signedUpAt: string | null;
  plan: Plan;
}

type MapResult = { ok: true; record: Account } | { ok: false; problems: string[] };

const mapAccount = (raw: RawAccount): MapResult => {
  const problems: string[] = [];
  const trimmed = (x: unknown): string => typeof x === 'string' ? x.trim() : '';
  const idText = trimmed(raw.account_id);
  const id = typeof raw.account_id === 'number' ? raw.account_id : /^\d+$/.test(idText) ? Number(idText) : NaN;
  if (id < 0 || !Number.isSafeInteger(id)) problems.push('account_id must be a whole number');
  const companyName = trimmed(raw.company_name);
  if (!companyName) problems.push('company_name must not be empty');
  const ownerEmail = trimmed(raw.owner_email).toLowerCase();
  if (ownerEmail.indexOf('@') < 0) problems.push('owner_email must contain @');
  const date = raw.signed_up_at;
  let signedUpAt: string | null = null;
  if (date !== undefined && date !== null) {
    if (typeof date !== 'string') problems.push('signed_up_at must be YYYY-MM-DD');
    else if (date.trim() !== '') {
      if (/^\d{4}-\d{2}-\d{2}$/.test(date.trim())) signedUpAt = date.trim();
      else problems.push('signed_up_at must be YYYY-MM-DD');
    }
  }
  const p = trimmed(raw.plan);
  let plan: Plan = 'starter';
  if (p === 'starter' || p === 'growth' || p === 'enterprise') plan = p;
  else problems.push('plan must be one of starter, growth or enterprise');
  if (problems.length) return {ok: false, problems: problems.sort()};
  return {ok: true, record: {id, companyName, ownerEmail, signedUpAt, plan}};
};

